example.code:
package main

import (
	"fmt"
	"strings"
)

func main() {
	file := "report_2024_final.pdf"
	fmt.Println("contains 2024:", strings.Contains(file, "2024"))
	fmt.Println("prefix report:", strings.HasPrefix(file, "report"))
	fmt.Println("suffix .pdf:", strings.HasSuffix(file, ".pdf"))
	first := strings.Index(file, "_")
	fmt.Println("first _:", first)
	fmt.Println("last _:", strings.LastIndex(file, "_"))
	fmt.Println("count _:", strings.Count(file, "_"))
	fmt.Println("index of zip:", strings.Index(file, "zip"))
	if first != -1 {
		fmt.Println("name:", file[:first])
	}
	fmt.Println("equal fold:", strings.EqualFold("PDF", "pdf"))
}

