practice.solution:
package main

import (
	"fmt"
	"strings"
)

func main() {
	email := "ada.lovelace@example.com"
	fmt.Println("contains @:", strings.Contains(email, "@"))
	fmt.Println("prefix ada:", strings.HasPrefix(email, "ada"))
	fmt.Println("suffix .org:", strings.HasSuffix(email, ".org"))
	at := strings.Index(email, "@")
	fmt.Println("first @:", at)
	fmt.Println("last .:", strings.LastIndex(email, "."))
	fmt.Println("count .:", strings.Count(email, "."))
	fmt.Println("index of #:", strings.Index(email, "#"))
	if at != -1 {
		fmt.Println("user:", email[:at])
	}
	fmt.Println("equal fold:", strings.EqualFold("ADA", "ada"))
}

