package main

import (
	"fmt"
	"strings"
)

func main() {
	colors := strings.Split("red,green,blue", ",")
	fmt.Println(len(colors), "colors")
	for i, c := range colors {
		fmt.Println(i, c)
	}
	fmt.Printf("%q\n", strings.Split("a,,b", ","))
	words := strings.Fields("  go   is   fun ")
	fmt.Println(len(words), "words:", words)
	fmt.Println(len(strings.Split("", ",")), len(strings.Fields("")))
	fmt.Println(strings.Join(colors, " | "))
}

