practice.solution:
package main

import (
	"fmt"
	"strings"
)

func main() {
	parts := strings.Split("2024-03-15", "-")
	fmt.Println(len(parts), "parts")
	for i, p := range parts {
		fmt.Println(i, p)
	}
	fmt.Println(strings.Join([]string{parts[2], parts[1], parts[0]}, "/"))
	fmt.Printf("%q\n", strings.Split("x;;y;z", ";"))
	words := strings.Fields("  the quick  brown fox ")
	fmt.Println(len(words), "words:", words)
	fmt.Println(len(strings.Split("", "-")), len(strings.Fields("   ")))
}
